import re

def test(keyword, replacement, text):
    py_keyword = re.sub(r'\(\?<([a-zA-Z_][a-zA-Z0-9_]*)>', r'(?P<\1>', keyword)
    rx = re.compile(py_keyword)

    def get_group(m, name):
        try:
            g = m.group(name if not name.isdigit() else int(name))
            return g if g is not None else ""
        except IndexError:
            return ""

    def repl_func(match):
        res = replacement
        res = res.replace('$$', '\x00')
        res = re.sub(r'\$(\d+)', lambda m: get_group(match, m.group(1)), res)
        res = re.sub(r'\$([a-zA-Z_][a-zA-Z0-9_]*)', lambda m: get_group(match, m.group(1)), res)
        res = re.sub(r'\$\{([^}]+)\}', lambda m: get_group(match, m.group(1)), res)
        res = res.replace('\x00', '$')
        return res

    return rx.sub(repl_func, text)

print(test('(aaa) (?<pat>bbb)', '$1 $pat ${1} ${pat}', 'aaa bbb'))
EOF
